import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, Send, Bot, User, Mic, MicOff } from 'lucide-react';
import './ChatPage.css';

const ChatPage = ({ userLocation }) => {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const messagesEndRef = useRef(null);

  // Mock AI responses for different farming queries
  const aiResponses = {
    'wheat': 'Wheat is best planted in October-November for winter wheat or February-March for spring wheat. Ensure well-drained soil with pH 6.0-7.5. Water regularly but avoid overwatering.',
    'tomato': 'Tomatoes thrive in warm weather. Plant after the last frost, 2-3 feet apart. They need 6-8 hours of sunlight daily and regular watering. Support with cages or stakes.',
    'rice': 'Rice requires standing water. Plant in flooded fields or use the SRI method. Maintain water level 2-4 inches during growth. Harvest when grains are firm and golden.',
    'pest': 'For pest control, try neem oil, companion planting, or introduce beneficial insects. Regular monitoring helps catch problems early. Consider organic pesticides.',
    'fertilizer': 'Use organic fertilizers like compost, manure, or vermicompost. Apply based on soil test results. Nitrogen for leafy growth, phosphorus for roots, potassium for fruits.',
    'weather': 'Check local weather forecasts regularly. Protect crops from extreme weather with covers or irrigation. Plan planting around seasonal patterns.',
    'harvest': 'Harvest timing is crucial. Look for color changes, firmness, and size. Use clean tools and handle produce gently. Store in cool, dry conditions.',
    'soil': 'Test soil pH and nutrient levels annually. Add organic matter to improve structure. Rotate crops to prevent nutrient depletion and disease buildup.',
    'irrigation': 'Water deeply but infrequently to encourage deep root growth. Use drip irrigation for efficiency. Water early morning to reduce evaporation.',
    'disease': 'Prevent diseases with crop rotation, proper spacing, and clean tools. Remove infected plants immediately. Use disease-resistant varieties when possible.'
  };

  useEffect(() => {
    // Auto-scroll to bottom when new messages arrive
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    // Welcome message
    addMessage('bot', 'Hello! I\'m your farming assistant. I can help you with crop advice, pest control, weather information, and more. What would you like to know about?');
  }, []);

  const addMessage = (sender, text) => {
    const newMessage = {
      id: Date.now(),
      sender,
      text,
      timestamp: new Date().toLocaleTimeString()
    };
    setMessages(prev => [...prev, newMessage]);
  };

  const generateAIResponse = (userMessage) => {
    const lowerMessage = userMessage.toLowerCase();

    // Simple keyword matching for demo
    for (const [keyword, response] of Object.entries(aiResponses)) {
      if (lowerMessage.includes(keyword)) {
        return response;
      }
    }

    // Default responses
    const defaultResponses = [
      'That\'s an interesting question about farming! Could you provide more specific details about what you\'re looking for?',
      'I\'d be happy to help with your farming query. What specific aspect would you like to know more about?',
      'For the best advice, please let me know what crop you\'re working with and any specific issues you\'re facing.',
      'I can help with crop selection, pest management, soil health, and more. What\'s your main concern?'
    ];

    return defaultResponses[Math.floor(Math.random() * defaultResponses.length)];
  };

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || isLoading) return;

    const userMessage = inputMessage.trim();
    setInputMessage('');
    setIsLoading(true);

    // Add user message
    addMessage('user', userMessage);

    // Simulate AI processing time
    setTimeout(() => {
      const aiResponse = generateAIResponse(userMessage);
      addMessage('bot', aiResponse);
      setIsLoading(false);
    }, 1000 + Math.random() * 2000); // Random delay between 1-3 seconds
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const toggleRecording = () => {
    setIsRecording(!isRecording);
    // In a real app, this would integrate with speech-to-text API
    if (!isRecording) {
      // Start recording
      console.log('Recording started...');
    } else {
      // Stop recording
      console.log('Recording stopped...');
      // Simulate speech-to-text result
      setTimeout(() => {
        setInputMessage('How to grow tomatoes?');
      }, 1000);
    }
  };

  const quickQuestions = [
    'How to grow wheat?',
    'Tomato pest control',
    'Best time to plant rice',
    'Soil testing methods',
    'Irrigation tips'
  ];

  return (
    <div className="chat-page page-transition">
      <div className="container">
        <div className="page-header">
          <h1 className="page-title">
            <MessageCircle className="page-icon" />
            AI Farming Assistant
          </h1>
          <p className="page-subtitle">Get instant advice on crops, pests, weather, and farming techniques</p>
        </div>

        <div className="chat-container">
          <div className="chat-messages">
            {messages.map((message) => (
              <div
                key={message.id}
                className={`message ${message.sender === 'user' ? 'user-message' : 'bot-message'}`}
              >
                <div className="message-avatar">
                  {message.sender === 'user' ? (
                    <User className="avatar-icon" />
                  ) : (
                    <Bot className="avatar-icon" />
                  )}
                </div>
                <div className="message-content">
                  <div className="message-text">{message.text}</div>
                  <div className="message-time">{message.timestamp}</div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="message bot-message">
                <div className="message-avatar">
                  <Bot className="avatar-icon" />
                </div>
                <div className="message-content">
                  <div className="typing-indicator">
                    <div className="typing-dot"></div>
                    <div className="typing-dot"></div>
                    <div className="typing-dot"></div>
                  </div>
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>

          <div className="quick-questions">
            <h3>Quick Questions</h3>
            <div className="question-chips">
              {quickQuestions.map((question, index) => (
                <button
                  key={index}
                  className="question-chip"
                  onClick={() => setInputMessage(question)}
                >
                  {question}
                </button>
              ))}
            </div>
          </div>

          <div className="chat-input-container">
            <div className="chat-input-wrapper">
              <textarea
                className="chat-input"
                placeholder="Ask me anything about farming..."
                value={inputMessage}
                onChange={(e) => setInputMessage(e.target.value)}
                onKeyPress={handleKeyPress}
                rows="1"
                disabled={isLoading}
              />
              <div className="input-actions">
                <button
                  className={`voice-btn ${isRecording ? 'recording' : ''}`}
                  onClick={toggleRecording}
                  disabled={isLoading}
                >
                  {isRecording ? <MicOff /> : <Mic />}
                </button>
                <button
                  className="send-btn"
                  onClick={handleSendMessage}
                  disabled={!inputMessage.trim() || isLoading}
                >
                  <Send />
                </button>
              </div>
            </div>
          </div>
        </div>

        <div className="chat-info">
          <div className="info-card">
            <h3>What I can help with:</h3>
            <ul>
              <li>🌾 Crop selection and growing tips</li>
              <li>🐛 Pest and disease identification</li>
              <li>🌤️ Weather and seasonal advice</li>
              <li>🌱 Soil health and fertilization</li>
              <li>💧 Irrigation and water management</li>
              <li>📅 Harvest timing and techniques</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatPage;
